// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount <= type(uint128).max);
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        uint256 balBefore = address(c).balance;
        vm.deal(actor, amount);
        vm.prank(actor);
        try c.deposit{value: amount}() { } catch { }
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == balBefore + amount);
    }
}
